function clampUnit(alpha) {
    if (Number.isNaN(alpha))
        return 1;
    return Math.min(1, Math.max(0, alpha));
}
/**
 * 基于根节点上的 `--glass-border-color`（任意合法 CSS 颜色）与透明度生成可用于渐变中的颜色。
 * 使用 color-mix，支持 #fff、rgb()、hsl()、颜色关键字、lab()、var() 等。
 */
export function glassBorderTint(alpha) {
    var pct = Math.round(clampUnit(alpha) * 100);
    return "color-mix(in srgb, var(--glass-border-color) ".concat(pct, "%, transparent)");
}
